if(popularGrid)popularGrid.innerHTML=popularIds.map(id=>{const t=toolDefs.find(x=>x.id===id);return `<a class="tool" href="${toolHref(t)}"><span class="tool-ico premium">${dkToolIcon(t)}</span><span><b>${t.name}</b><small>${t.desc}</small></span></a>`}).join('');
