function renderJson(mode='json'){
 const box=$('jsonPanel'); if(!box)return;
 if(mode==='json') box.innerHTML=`<div class="field"><label>JSON</label><textarea id="jsonText" placeholder='{"name":"DoKitly"}'></textarea></div><div class="action-row"><button class="primary" id="jsonFormat">Format</button><button class="secondary" id="jsonMinify">Minify</button><button class="secondary" id="jsonValidate">Validate</button></div><div class="output" id="jsonOut">Paste JSON and choose an action.</div>`;
 else box.innerHTML=`<div class="field"><label>Normal text</label><textarea id="plainText" placeholder="Paste any text here..."></textarea></div><div class="form-grid"><div class="field"><label>JSON key name</label><input id="textKey" value="text"></div><div class="field"><label>Mode</label><select id="textJsonMode"><option value="single">Whole text as one value</option><option value="lines">Each line as array item</option><option value="pairs">key: value lines → object</option></select></div></div><div class="action-row"><button class="primary" id="textToJson">Convert to JSON</button></div><div class="output" id="jsonOut">Your converted JSON will appear here.</div>`;
 bindJsonPanel(mode);
}

function bindJsonPanel(mode){
 if(mode==='json'){
  $('jsonFormat').onclick=()=>jsonAction('format'); $('jsonMinify').onclick=()=>jsonAction('minify'); $('jsonValidate').onclick=()=>jsonAction('validate');
 } else {
  $('textToJson').onclick=()=>{
   const key=($('textKey').value.trim()||'text');
   const raw=$('plainText').value;
   const mode=$('textJsonMode').value;
   let obj;
   if(mode==='lines'){
    obj={[key]:raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)};
   }else if(mode==='pairs'){
    obj={};
    raw.split(/\r?\n/).filter(Boolean).forEach((line,i)=>{
     const idx=line.indexOf(':');
     if(idx>-1){const k=line.slice(0,idx).trim()||`field${i+1}`;obj[k]=line.slice(idx+1).trim()}
     else obj[`field${i+1}`]=line.trim();
    });
   }else{
    obj={[key]:raw};
   }
   const pretty=JSON.stringify(obj,null,2);
   $('jsonOut').innerHTML=`<pre>${escapeHtml(pretty)}</pre><div class="action-row"><button class="secondary" id="copyJson">Copy JSON</button></div>`;
   $('copyJson').onclick=async()=>{try{await navigator.clipboard.writeText(pretty);$('copyJson').textContent='Copied ✓'}catch{}};
  };
 }
}
function jsonAction(type){
 const out=$('jsonOut'),txt=$('jsonText').value;
 try{const parsed=JSON.parse(txt);if(type==='format')$('jsonText').value=JSON.stringify(parsed,null,2);if(type==='minify')$('jsonText').value=JSON.stringify(parsed);out.innerHTML=`<strong>Valid JSON ✓</strong><small>${type==='validate'?'No formatting changes made.':'Done successfully.'}</small>`}catch(e){out.innerHTML=`<strong>Invalid JSON</strong><small>${escapeHtml(e.message)}</small>`}
}

