 if(id==='image-color'){$('simpleFile').onchange=async()=>{try{const {img}=await readImage($('simpleFile').files[0]);const c=$('colorCanvas'),max=720,scale=Math.min(1,max/img.width);c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);c.onclick=e=>{const r=c.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*c.width/r.width),y=Math.floor((e.clientY-r.top)*c.height/r.height),d=c.getContext('2d').getImageData(x,y,1,1).data,hex='#'+[d[0],d[1],d[2]].map(v=>v.toString(16).padStart(2,'0')).join('').toUpperCase();$('simpleOut').innerHTML=`<strong>${hex}</strong><small>RGB(${d[0]}, ${d[1]}, ${d[2]}) • pixel ${x}, ${y}</small>`}}catch(e){$('simpleOut').textContent=e.message}};return}
