// Build 6 hero buddy: spring-letter physics across every headline letter.
(function initHeroBuddy(){
 const wrap=document.querySelector('.hero-title-wrap'),mover=document.querySelector('.hero-buddy-mover'),buddy=document.querySelector('.hero-buddy'),shadow=document.querySelector('.hero-buddy-shadow');
 if(!wrap||!mover||!buddy)return;
 const targets=[...wrap.querySelectorAll('.spring-letter')];
 if(!targets.length)return;
 let current=0,timer=null,animating=false,lastIndex=-1;
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 function landingPoint(el){
  const wr=wrap.getBoundingClientRect(),tr=el.getBoundingClientRect(),mw=mover.offsetWidth,mh=mover.offsetHeight;
  // Bottom of icon visually meets the top of the exact letter.
  return {x:tr.left-wr.left+tr.width/2-mw/2,y:tr.top-wr.top-mh*.72+11};
 }
 function place(i){const p=landingPoint(targets[i]);mover.style.left=p.x+'px';mover.style.top=p.y+'px';mover.style.transform='translate3d(0,0,0)'}
 function chooseNext(){
  if(targets.length<2)return 0;
  let n=current,guard=0;
  while((n===current||n===lastIndex)&&guard++<20)n=Math.floor(Math.random()*targets.length);
  return n;
 }
 function schedule(){clearTimeout(timer);if(!reduced)timer=setTimeout(hop,520+Math.random()*820)}
 function springLetter(el,dir=1){
  el.getAnimations().forEach(a=>a.cancel());
  return el.animate([
   {transform:'translateY(0) scaleY(1)',offset:0},
   {transform:'translateY(5px) scaleY(.78) scaleX(1.08)',offset:.18},
   {transform:'translateY(-11px) scaleY(1.13) scaleX(.96)',offset:.44},
   {transform:`translateY(3px) rotate(${dir*.7}deg) scaleY(.96)`,offset:.68},
   {transform:'translateY(-2px) scaleY(1.035)',offset:.84},
   {transform:'translateY(0) scaleY(1)',offset:1}
  ],{duration:430,easing:'cubic-bezier(.2,.9,.24,1)'});
 }
 async function hop(){
  if(animating||document.hidden)return schedule();
  const next=chooseNext(),from=landingPoint(targets[current]),to=landingPoint(targets[next]);
  const dx=to.x-from.x,dy=to.y-from.y,dist=Math.hypot(dx,dy),dir=dx>=0?1:-1;
  const height=Math.max(58,Math.min(138,54+dist*.23));
  const duration=Math.max(600,Math.min(1040,560+dist*.95));
  animating=true;
  mover.style.left=from.x+'px';mover.style.top=from.y+'px';

  // The current letter behaves like a spring and launches the icon.
  const launchLetter=springLetter(targets[current],dir);
  await Promise.all([
   buddy.animate([
    {transform:'translateY(1px) scale(1.05,.92)',offset:0},
    {transform:'translateY(5px) scale(1.11,.84)',offset:.32},
    {transform:'translateY(-5px) scale(.96,1.08)',offset:.72},
    {transform:'translateY(0) scale(1)',offset:1}
   ],{duration:210,easing:'cubic-bezier(.3,0,.45,1)',fill:'forwards'}).finished.catch(()=>{}),
   new Promise(r=>setTimeout(r,128))
  ]);

  const frames=[],steps=22;
  for(let i=0;i<=steps;i++){
   const t=i/steps,x=dx*t,y=dy*t-4*height*t*(1-t),spin=dir*(Math.sin(Math.PI*t)*13+t*5);
   frames.push({transform:`translate3d(${x}px,${y}px,0) rotate(${spin}deg)`,offset:t});
  }
  const travel=mover.animate(frames,{duration,easing:'linear',fill:'forwards'});
  const body=buddy.animate([
   {transform:'scale(.97,1.06)',offset:0},
   {transform:'scale(1)',offset:.22},
   {transform:'scale(1)',offset:.72},
   {transform:'scale(1.025,.97)',offset:1}
  ],{duration,easing:'linear',fill:'forwards'});
  const shade=shadow?.animate([
   {transform:'scaleX(.92)',opacity:.40,offset:0},
   {transform:'scaleX(.35)',opacity:.09,offset:.50},
   {transform:'scaleX(.95)',opacity:.43,offset:1}
  ],{duration,easing:'ease-in-out',fill:'forwards'});
  await travel.finished.catch(()=>{});
  launchLetter.cancel();
  mover.style.left=to.x+'px';mover.style.top=to.y+'px';mover.style.transform='translate3d(0,0,0)';
  travel.cancel();body.cancel();shade?.cancel();

  // True contact: target letter compresses first, then pushes the icon back up.
  const impactLetter=springLetter(targets[next],dir);
  await buddy.animate([
   {transform:'translateY(3px) scale(1.10,.86)',offset:0},
   {transform:'translateY(7px) scale(1.13,.82)',offset:.16},
   {transform:'translateY(-13px) scale(.96,1.10)',offset:.46},
   {transform:'translateY(2px) scale(1.025,.975)',offset:.72},
   {transform:'translateY(-2px) scale(.99,1.02)',offset:.86},
   {transform:'translateY(0) scale(1)',offset:1}
  ],{duration:430,easing:'cubic-bezier(.18,.9,.24,1)'}).finished.catch(()=>{});
  impactLetter.cancel();
  shadow?.animate([
   {transform:'scaleX(1.08)',opacity:.48},
   {transform:'scaleX(.72)',opacity:.25,offset:.45},
   {transform:'scaleX(.88)',opacity:.36}
  ],{duration:380,easing:'ease-out'});
  lastIndex=current;current=next;animating=false;schedule();
 }
 requestAnimationFrame(()=>{place(0);schedule()});
 window.addEventListener('resize',()=>{if(!animating)place(current)},{passive:true});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!animating){place(current);schedule()}});
})();



