/* Build 7 PDF hover reliability patch
   Keeps the PDF category menu open on hover/focus and closes cleanly outside. */
(() => {
  const card = document.querySelector('.cat[data-category="PDF & Document"]');
  const menu = document.getElementById('pdfHoverMenu');
  if (!card || !menu || typeof showPdfHoverMenu !== 'function') return;

  let closeTimer = null;
  const cancelClose = () => { if (closeTimer) { clearTimeout(closeTimer); closeTimer = null; } };
  const open = () => { cancelClose(); showPdfHoverMenu(card); };
  const close = (delay = 220) => {
    cancelClose();
    closeTimer = setTimeout(() => {
      if (card.matches(':hover') || menu.matches(':hover') || card.contains(document.activeElement) || menu.contains(document.activeElement)) return;
      menu.classList.remove('show');
      setTimeout(() => {
        if (!menu.classList.contains('show')) {
          menu.hidden = true;
          menu.setAttribute('aria-hidden','true');
        }
      }, 180);
    }, delay);
  };

  card.addEventListener('pointerenter', open);
  card.addEventListener('pointerleave', () => close());
  card.addEventListener('focusin', open);
  card.addEventListener('focusout', () => close());
  menu.addEventListener('pointerenter', cancelClose);
  menu.addEventListener('pointerleave', () => close());
  menu.addEventListener('focusin', cancelClose);
  menu.addEventListener('focusout', () => close());

  document.addEventListener('pointerdown', (e) => {
    if (!card.contains(e.target) && !menu.contains(e.target)) close(0);
  });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') close(0); });

  const reposition = () => {
    if (!menu.hidden && menu.classList.contains('show')) showPdfHoverMenu(card);
  };
  window.addEventListener('resize', reposition, {passive:true});
  window.addEventListener('scroll', reposition, {passive:true});
})();

/* Build 7 global branded color picker enhancer for simple/home tool views. */
(()=>{const sw=['#111827','#ffffff','#2563eb','#14b8a6','#ef4444','#f59e0b','#8b5cf6','#ec4899'];function enhance(i){if(!i||i.dataset.dmoColor)return;i.dataset.dmoColor='1';const label=i.closest('.field')?.querySelector('label')?.textContent?.trim()||'Color';const w=document.createElement('div');w.className='global-color-orb';const b=document.createElement('button');b.type='button';b.className='global-color-btn';b.innerHTML=`<span></span><b>${escapeHtml(label)}</b><em>⌄</em>`;const p=document.createElement('div');p.className='global-color-pop';p.hidden=true;i.parentNode.insertBefore(w,i);w.append(b,p);sw.forEach(c=>{const x=document.createElement('button');x.type='button';x.style.setProperty('--c',c);x.title=c;x.addEventListener('click',e=>{e.stopPropagation();i.value=c;i.dispatchEvent(new Event('input',{bubbles:true}));i.dispatchEvent(new Event('change',{bubbles:true}));p.hidden=true});p.appendChild(x)});const l=document.createElement('label');l.title='Custom color';l.textContent='＋';l.appendChild(i);p.appendChild(l);const sync=()=>{b.firstElementChild.style.background=i.value;b.setAttribute('aria-label',`${label}: ${i.value}`)};b.addEventListener('click',e=>{e.stopPropagation();document.querySelectorAll('.global-color-pop').forEach(q=>{if(q!==p)q.hidden=true});p.hidden=!p.hidden});i.addEventListener('input',sync);i.addEventListener('change',sync);sync()}function scan(){document.querySelectorAll('input[type=color]').forEach(enhance)}document.addEventListener('click',()=>document.querySelectorAll('.global-color-pop').forEach(p=>p.hidden=true));if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',scan);else scan();new MutationObserver(scan).observe(document.body,{childList:true,subtree:true})})();

